function delQ(id) {
  if (confirm('Delete this quiz? This cannot be undone.')) {
    deleteQuiz(id);
    showToast('Quiz deleted.', 'info');
    setTimeout(() => location.reload(), 600);
  }
}

function exportData() {
  const db = getDB();
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(db, null, 2));
  const downloadAnchor = document.createElement('a');
  downloadAnchor.setAttribute("href", dataStr);
  downloadAnchor.setAttribute("download", `alaquizpedia_db_${Date.now()}.json`);
  document.body.appendChild(downloadAnchor);
  downloadAnchor.click();
  downloadAnchor.remove();
  showToast('✅ Database backup downloaded!', 'success');
}

function importData(e) {
  const file = e.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(evt) {
    const res = importDatabase(evt.target.result);
    if (res.success) {
      showToast('✅ Database restored successfully!', 'success');
      setTimeout(() => location.reload(), 1000);
    } else {
      showToast('❌ Import failed: ' + res.error, 'error');
    }
  };
  reader.readAsText(file);
}

