    }

    /* ---- Share Modal Link Generator ---- */
    let currentShareId = '';

    function openShareModal(id, title) {
      currentShareId = id;
      document.getElementById('shareQuizTitle').textContent = title;
      document.getElementById('shareModal').classList.remove('hidden');

      // Reset inputs
      document.getElementById('optNoTimer').checked = false;
      document.getElementById('optFeedback').checked = true;
      document.getElementById('optPlayerName').value = '';

      updateGeneratedUrl();
    }

    function closeShareModal() {
      document.getElementById('shareModal').classList.add('hidden');
    }

    function updateGeneratedUrl() {
      if (!currentShareId) return;

      let baseUrl = window.location.origin + window.location.pathname.replace('admin-quizzes.html', 'quiz-player.html');
      // If running locally as file://
      if (window.location.protocol === 'file:') {
        baseUrl = window.location.href.replace('admin-quizzes.html', 'quiz-player.html');
        // split query if any
        baseUrl = baseUrl.split('?')[0];
      }

      let url = `${baseUrl}?id=${currentShareId}`;

      if (document.getElementById('optNoTimer').checked) {
        url += '&timer=off';
      }
      if (!document.getElementById('optFeedback').checked) {
        url += '&feedback=off';
      }
      const player = document.getElementById('optPlayerName').value.trim();
      if (player) {
        url += `&player=${encodeURIComponent(player)}`;
      }

      document.getElementById('generatedUrlInput').value = url;
    }

    function copyShareLink() {
      const input = document.getElementById('generatedUrlInput');
      input.select();
      input.setSelectionRange(0, 99999);
      navigator.clipboard.writeText(input.value).then(() => {
        showToast('📋 Share link copied to clipboard!', 'success');
      });
    }

    render();
  </script>

