requireAdmin();

const params = new URLSearchParams(window.location.search);
const editId = params.get('id');
const autoGenerate = params.get('generate');
let questions = [];
let editingQuiz = null;

// Load Gemini Key from localStorage
const savedKey = localStorage.getItem('gemini_api_key');
if (savedKey) {
  document.getElementById('geminiApiKey').value = savedKey;
}

// Populate Cover Image dropdown
populateImageSelects();

// Load existing quiz if editing
if (editId) {
  editingQuiz = getQuizById(editId);
  if (editingQuiz) {
    document.getElementById('pageTitle').innerHTML = '✏️ Edit <span class="gradient-text">Quiz</span>';
    document.getElementById('quizTitle').value = editingQuiz.title;
    document.getElementById('quizDesc').value = editingQuiz.description || '';
    document.getElementById('quizCategory').value = editingQuiz.category || 'General';
    document.getElementById('quizDifficulty').value = editingQuiz.difficulty || 'Medium';
    document.getElementById('timePerQ').value = editingQuiz.timePerQuestion || 30;
    if (editingQuiz.imageId) {
      document.getElementById('quizCoverImage').value = editingQuiz.imageId;
      previewQuizCover();
    }
    questions = [...(editingQuiz.questions || [])];
    renderAllQuestions();
  }
}

// Auto-focus generate if ?generate=1
if (autoGenerate) {
  document.getElementById('topicInput').focus();
  showToast('Type a topic name and click Generate!', 'info', 4000);
}

