args.ReplacementContent:
function renderQuestionEditor(q, i) {
  const typeLabels = { mcq: 'Multiple Choice', truefalse: 'True / False', fillinblank: 'Fill in the Blank' };
  let optionsHtml = '';

  if (q.type === 'mcq') {
    const opts = (q.options && q.options.length >= 4) ? q.options : ['','','',''];
    optionsHtml = `
      <div style="margin-bottom:0.75rem;font-size:0.82rem;color:var(--text-muted);">Options (radio = correct answer):</div>
      ${opts.map((opt,oi)=>`
        <div class="option-row">
          <input type="radio" class="correct-radio" name="correct_${i}" value="${oi}" ${q.correctAnswer === opt && opt ? 'checked' : ''} onchange="updateCorrectByIndex(${i},${oi})"/>
          <input type="text" class="form-input" style="flex:1;" placeholder="Option ${String.fromCharCode(65+oi)}" value="${escVal(opt)}" oninput="updateOption(${i},${oi},this.value)"/>
        </div>
      `).join('')}
    `;
  } else if (q.type === 'truefalse') {
    optionsHtml = `
      <div style="margin-bottom:0.5rem;font-size:0.82rem;color:var(--text-muted);">Correct Answer:</div>
      <div style="display:flex;gap:1rem;">
        <label style="display:flex;align-items:center;gap:0.4rem;cursor:pointer;font-size:0.9rem;">
          <input type="radio" name="tf_${i}" value="True" ${q.correctAnswer==='True'?'checked':''} onchange="updateCorrectAnswer(${i},'True')"/> True
        </label>
        <label style="display:flex;align-items:center;gap:0.4rem;cursor:pointer;font-size:0.9rem;">
          <input type="radio" name="tf_${i}" value="False" ${q.correctAnswer==='False'?'checked':''} onchange="updateCorrectAnswer(${i},'False')"/> False
        </label>
      </div>
    `;
  } else {
    optionsHtml = `
      <div class="form-group" style="margin-bottom:0;">
        <label class="form-label">Correct Answer</label>
        <input type="text" class="form-input" placeholder="The answer to fill in" value="${escVal(q.correctAnswer)}" oninput="updateCorrectAnswer(${i},this.value)"/>
      </div>
    `;
  }

  const images = getImages();
  let imgSelectHtml = `
    <div class="form-group" style="margin-top:0.75rem;">
      <label class="form-label">Question Image (Optional)</label>
      <select class="form-select" onchange="updateQuestionImage(${i}, this.value)">
        <option value="">No Image</option>
        ${images.map(img => `<option value="${img.id}" ${q.imageId === img.id ? 'selected' : ''}>${img.name}</option>`).join('')}
      </select>
      <div id="qImgPreview_${i}" style="margin-top:0.5rem; max-width:150px; display:${q.imageId ? 'block' : 'none'};">
        <img src="${q.imageId ? (images.find(im=>im.id===q.imageId)||{data:''}).data : ''}" style="width:100%; height:auto; border-radius:6px; border:1px solid var(--border-color);" alt="Question Preview"/>
      </div>
    </div>
  `;

  return `
    <div class="question-editor" id="qed_${i}" style="animation:fadeSlideIn 0.3s ease;">
      <div class="q-editor-header">
        <span class="q-editor-num">Q${i+1} — <span class="badge badge-blue" style="font-size:0.75rem;">${typeLabels[q.type]||q.type}</span></span>
        <div style="display:flex;gap:0.5rem;">
          ${i > 0 ? `<button class="btn btn-ghost btn-sm" onclick="moveQ(${i},-1)" title="Move up">↑</button>` : ''}
          ${i < questions.length-1 ? `<button class="btn btn-ghost btn-sm" onclick="moveQ(${i},1)" title="Move down">↓</button>` : ''}
          <button class="btn btn-danger btn-sm" onclick="removeQ(${i})">🗑 Remove</button>
        </div>
      </div>
      <div class="form-group">
        <label class="form-label">Question Text *</label>
        <textarea class="form-textarea" rows="2" placeholder="Enter your question here..." oninput="updateQText(${i},this.value)">${escVal(q.questionText)}</textarea>
      </div>
      <div id="opts_${i}">${optionsHtml}</div>
      ${imgSelectHtml}
      <div class="form-group" style="margin-top:0.75rem;margin-bottom:0;">
        <label class="form-label">Explanation (optional)</label>
        <input type="text" class="form-input" placeholder="Explain the correct answer..." value="${escVal(q.explanation)}" oninput="updateExplanation(${i},this.value)"/>
      </div>
    </div>
  `;
}

