36: /**
37:  * Main entry point: Generate questions from a topic string
38:  * Returns array of question objects
39:  */
40: async function generateQuestionsFromTopic(topic, count = 10) {
41:   const apiKey = localStorage.getItem('gemini_api_key');
42:   if (apiKey) {
43:     try {
44:       return await generateFromGemini(apiKey, topic, count);
45:     } catch (e) {
46:       console.warn('Gemini API failed, falling back to offline methods:', e);
47:     }
48:   }
49: 
50:   const topicLower = topic.toLowerCase().trim();
51:   const triviaId = TRIVIA_CATEGORIES[topicLower];
52: 
53:   let questions = [];
54: 
55:   // Step 1: Try Open Trivia DB if we have a matching category
56:   if (triviaId) {
57:     try {
58:       questions = await fetchFromTrivia(triviaId, count);
59:     } catch(e) {
60:       console.warn('Trivia DB failed, trying Wikipedia...', e);
61:     }
62:   }
63: 
64:   // Step 2: If not enough questions, supplement with Wikipedia-based generation
65:   if (questions.length < 5) {
66:     try {
67:       const wikiQuestions = await generateFromWikipedia(topic, count - questions.length);
68:       questions = [...questions, ...wikiQuestions];
69:     } catch(e) {
70:       console.warn('Wikipedia generation failed:', e);
71:     }
72:   }
73: 
74:   // Step 3: If still nothing, use built-in fallback
75:   if (questions.length === 0) {
76:     questions = generateFallbackQuestions(topic);
77:   }
78: 
79:   return questions.slice(0, count);
80: }
