82: /* ---- Google Gemini AI Generator ---- */
83: async function generateFromGemini(apiKey, topic, count) {
84:   const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey}`;
85:   
86:   const systemPrompt = `You are a professional quiz maker for a general knowledge app called ALA QUIZPEDIA.
87: Your task is to generate a list of ${count} high-quality trivia questions about the topic "${topic}".
88: Each question can be one of three types:
89: 1. "mcq" (Multiple Choice Question, must have exactly 4 options and 1 correctAnswer matching one of the options)
90: 2. "truefalse" (True or False, options must be ["True", "False"], correctAnswer must be "True" or "False")
91: 3. "fillinblank" (Fill in the blank, options must be an empty array [], correctAnswer must be a short string)
92: 
93: Format your response as a valid JSON array of objects matching this exact structure:
94: [
95:   {
96:     "type": "mcq" | "truefalse" | "fillinblank",
97:     "questionText": "The text of the question",
98:     "options": ["Option A", "Option B", "Option C", "Option D"], // or [] for fillinblank, or ["True", "False"] for truefalse
99:     "correctAnswer": "The exact string of the correct option or correct fill-in value",
100:     "explanation": "A short sentence explaining why this is correct"
101:   }
102: ]
103: 
104: Do not include any markdown format tags, backticks, or any text other than the JSON itself. It must be directly parseable by JSON.parse.`;
105: 
106:   const payload = {
107:     contents: [
108:       {
109:         parts: [
110:           {
111:             text: systemPrompt
112:           }
113:         ]
114:       }
115:     ],
116:     generationConfig: {
117:       responseMimeType: "application/json"
118:     }
119:   };
120: 
121:   const response = await fetch(url, {
122:     method: 'POST',
123:     headers: {
124:       'Content-Type': 'application/json'
125:     },
126:     body: JSON.stringify(payload)
127:   });
128: 
129:   if (!response.ok) {
130:     const errText = await response.text();
131:     throw new Error(`Gemini Error: ${response.status} - ${errText}`);
132:   }
133: 
134:   const resData = await response.json();
135:   const rawText = resData.candidates[0].content.parts[0].text;
136:   
137:   const questions = JSON.parse(rawText);
138:   if (!Array.isArray(questions)) {
139:     throw new Error("Invalid response format from Gemini.");
140:   }
141: 
142:   return questions.map(q => ({
143:     id: 'q-' + Math.random().toString(36).substr(2, 9),
144:     type: q.type || 'mcq',
145:     questionText: q.questionText,
146:     options: q.options || [],
147:     correctAnswer: q.correctAnswer,
148:     explanation: q.explanation || ''
149:   }));
150: }
151: 
152: 
153: /* ---- Open Trivia DB Fetcher ---- */
154: async function fetchFromTrivia(categoryId, count) {
155:   const url = `https://opentdb.com/api.php?amount=${count}&category=${categoryId}&type=multiple&encode=base64`;
156:   const res = await fetch(url);
157:   const data = await res.json();
158: 
159:   if (data.response_code !== 0 || !data.results) return [];
160: 
161:   return data.results.map(q => {
162:     const correct = atob(q.correct_answer);
163:     const incorrects = q.incorrect_answers.map(a => atob(a));
164:     const options = shuffle([correct, ...incorrects]);
165:     return {
166:       id: genId('q'),
167:       type: 'mcq',
168:       questionText: atob(q.question),
169:       options,
170:       correctAnswer: correct,
171:       explanation: `Difficulty: ${atob(q.difficulty || '')}`
172:     };
173:   });
174: }
175: 
176: /* ---- Wikipedia Content → Questions ---- */
177: async function generateFromWikipedia(topic, count) {
178:   // Fetch Wikipedia summary
179:   const url = `https://en.wikipedia.org/w/api.php?action=query&titles=${encodeURIComponent(topic)}&prop=extracts&exintro=true&explaintext=true&format=json&origin=*`;
180:   const res = await fetch(url);
181:   const data = await res.json();
182: 
183:   const pages = data.query.pages;
184:   const page = Object.values(pages)[0];
185: 
186:   if (!page || page.missing !== undefined || !page.extract) {
187:     return [];
188:   }
189: 
190:   const text = page.extract;
191:   return parseTextToQuestions(text, topic, count);
192: }
193: 
194: /* ---- Parse Wikipedia text into questions ---- */
195: function parseTextToQuestions(text, topic, count) {
196:   const questions = [];
197: 
198:   // Split into sentences
199:   const sentences = text
200:     .replace(/\n+/g, ' ')
201:     .split(/(?<=[.!?])\s+/)
202:     .filter(s => s.length > 40 && s.length < 300)
203:     .filter(s => !s.startsWith('==') && !s.match(/^\d+$/));
204: 
205:   // Strategy 1: Fill-in-the-blank (remove key noun from sentence)
206:   sentences.slice(0, Math.ceil(count * 0.4)).forEach(sentence => {
207:     const words = sentence.split(' ');
208:     // Find a capitalized word (likely a proper noun / key term)
209:     const keyWordIdx = words.findIndex((w, i) => i > 0 && /^[A-Z][a-z]{3,}/.test(w) && !['The','This','That','These','Those','When','Where','While','Although'].includes(w));
210: 
211:     if (keyWordIdx > -1) {
212:       const keyWord = words[keyWordIdx].replace(/[.,;:]$/, '');
213:       const blank = sentence.replace(words[keyWordIdx], '______');
214:       questions.push({
215:         id: genId('q'),
216:         type: 'fillinblank',
217:         questionText: `Fill in the blank: "${blank}"`,
218:         options: [],
219:         correctAnswer: keyWord,
220:         explanation: `From Wikipedia: ${sentence}`
221:       });
222:     }
223:   });
224: 
225:   // Strategy 2: True/False — alter a sentence slightly
226:   sentences.slice(Math.ceil(count * 0.4), Math.ceil(count * 0.7)).forEach(sentence => {
227:     const isTrue = Math.random() > 0.5;
228:     let questionSentence = sentence;
229: 
230:     if (!isTrue) {
231:       // Flip numbers or replace key words with plausible alternatives
232:       questionSentence = flipFact(sentence);
233:     }
234: 
235:     questions.push({
236:       id: genId('q'),
237:       type: 'truefalse',
238:       questionText: `True or False: "${questionSentence}"`,
239:       options: ['True', 'False'],
240:       correctAnswer: isTrue ? 'True' : 'False',
241:       explanation: `Original: ${sentence}`
242:     });
243:   });
244: 
245:   // Strategy 3: "What is X known for?" MCQ
246:   if (sentences.length > 0) {
247:     const firstSentence = sentences[0];
248:     questions.push({
249:       id: genId('q'),
250:       type: 'mcq',
251:       questionText: `According to general knowledge, what is "${topic}" primarily associated with?`,
252:       options: generateDistractors(topic, firstSentence),
253:       correctAnswer: extractKeyPhrase(firstSentence, topic),
254:       explanation: firstSentence
255:     });
256:   }
257: 
258:   return questions.filter(q => q.questionText && q.correctAnswer).slice(0, count);
259: }
260: 
261: /* ---- Helper: Extract key phrase from sentence ---- */
262: function extractKeyPhrase(sentence, topic) {
263:   // Take the main predicate after "is" or "was"
264:   const match = sentence.match(/(?:is|was|are|were)\s+(?:a|an|the)?\s*([^,.]{3,40})/i);
