/* ================================================
    quiz-generator.js
    Topic → Auto-generate questions
    Uses: Open Trivia DB + Wikipedia APIs
    ALA QUIZPEDIA by A.SHAM SHARAN
    ================================================ */

// Category mapping for Open Trivia DB
const TRIVIA_CATEGORIES = {
  'general':       9,  'general knowledge': 9,
  'books':         10, 'literature': 10,
  'films':         11, 'movies': 11, 'cinema': 11,
  'music':         12,
  'theatre':       13, 'theater': 13,
  'television':    14, 'tv': 14,
  'gaming':        15, 'games': 15, 'video games': 15,
  'board games':   16,
  'science':       17, 'science \u0026 nature': 17, 'nature': 17, 'biology': 17, 'physics': 17, 'chemistry': 17,
  'computers':     18, 'technology': 18, 'computer': 18, 'programming': 18,
  'mathematics':   19, 'maths': 19, 'math': 19,
  'mythology':     20,
  'sports':        21, 'sport': 21,
  'geography':     22, 'world geography': 22, 'countries': 22,
  'history':       23, 'world history': 23,
  'politics':      24,
  'art':           25,
  'celebrities':   26, 'celebrity': 26,
  'animals':       27, 'zoology': 27,
  'vehicles':      28, 'cars': 28,
  'comics':        29,
  'gadgets':       30,
  'anime':         31, 'manga': 31,
  'cartoon':       32, 'cartoons': 32
};

/**
 * Main entry point: Generate questions from a topic string
 * Returns array of question objects
 */
async function generateQuestionsFromTopic(topic, count = 10) {
  const apiKey = localStorage.getItem('gemini_api_key');
  if (apiKey) {
    try {
      return await generateFromGemini(apiKey, topic, count);
    } catch (e) {
      console.warn('Gemini API failed, falling back to offline methods:', e);
    }
  }

  const topicLower = topic.toLowerCase().trim();
  const triviaId = TRIVIA_CATEGORIES[topicLower];

  let questions = [];

  // Step 1: Try Open Trivia DB if we have a matching category
  if (triviaId) {
    try {
      questions = await fetchFromTrivia(triviaId, count);
    } catch(e) {
      console.warn('Trivia DB failed, trying Wikipedia...', e);
    }
  }

  // Step 2: If not enough questions, supplement with Wikipedia-based generation
  if (questions.length < 5) {
    try {
      const wikiQuestions = await generateFromWikipedia(topic, count - questions.length);
      questions = [...questions, ...wikiQuestions];
    } catch(e) {
      console.warn('Wikipedia generation failed:', e);
    }
  }

  // Step 3: If still nothing, use built-in fallback
  if (questions.length === 0) {
    questions = generateFallbackQuestions(topic);
  }

  return questions.slice(0, count);
}

/* ---- Google Gemini AI Generator ---- */
async function generateFromGemini(apiKey, topic, count) {
  const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey}`;

  const systemPrompt = `You are a professional quiz maker for a general knowledge app called ALA QUIZPEDIA.
Your task is to generate a list of ${count} high-quality trivia questions about the topic "${topic}".
Each question can be one of three types:
1. "mcq" (Multiple Choice Question, must have exactly 4 options and 1 correctAnswer matching one of the options)
2. "truefalse" (True or False, options must be ["True", "False"], correctAnswer must be "True" or "False")
3. "fillinblank" (Fill in the blank, options must be an empty array [], correctAnswer must be a short string)

Format your response as a valid JSON array of objects matching this exact structure:
[
  {
    "type": "mcq" | "truefalse" | "fillinblank",
    "questionText": "The text of the question",
    "options": ["Option A", "Option B", "Option C", "Option D"], // or [] for fillinblank, or ["True", "False"] for truefalse
    "correctAnswer": "The exact string of the correct option or correct fill-in value",
    "explanation": "A short sentence explaining why this is correct"
  }
]

Do not include any markdown format tags, backticks, or any text other than the JSON itself. It must be directly parseable by JSON.parse.`;

  const payload = {
    contents: [
      {
        parts: [
          {
            text: systemPrompt
          }
        ]
      }
    ],
    generationConfig: {
      responseMimeType: "application/json"
    }
  };

  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(payload)
  });

  if (!response.ok) {
    const errText = await response.text();
    throw new Error(`Gemini Error: ${response.status} - ${errText}`);
  }

  const resData = await response.json();
  const rawText = resData.candidates[0].content.parts[0].text;

  const questions = JSON.parse(rawText);
  if (!Array.isArray(questions)) {
    throw new Error("Invalid response format from Gemini.");
  }

  return questions.map(q => ({
    id: 'q-' + Math.random().toString(36).substr(2, 9),
    type: q.type || 'mcq',
    questionText: q.questionText,
    options: q.options || [],
    correctAnswer: q.correctAnswer,
    explanation: q.explanation || ''
  }));
}

/* ---- Open Trivia DB Fetcher ---- */
async function fetchFromTrivia(categoryId, count) {
  const url = `https://opentdb.com/api.php?amount=${count}\u0026category=${categoryId}\u0026type=multiple\u0026encode=base64`;
  const res = await fetch(url);
  const data = await res.json();

  if (data.response_code !== 0 || !data.results) return [];

  return data.results.map(q => {
    const correct = atob(q.correct_answer);
    const incorrects = q.incorrect_answers.map(a => atob(a));
    const options = shuffle([correct, ...incorrects]);
    return {
      id: genId('q'),
      type: 'mcq',
      questionText: atob(q.question),
      options,
      correctAnswer: correct,
      explanation: `Difficulty: ${atob(q.difficulty || '')}`
    };
  });
}

/* ---- Wikipedia Content → Questions ---- */
async function generateFromWikipedia(topic, count) {
  // Fetch Wikipedia summary
  const url = `https://en.wikipedia.org/w/api.php?action=query\u0026titles=${encodeURIComponent(topic)}\u0026prop=extracts\u0026exintro=true\u0026explaintext=true\u0026format=json\u0026origin=*`;
  const res = await fetch(url);
  const data = await res.json();

  const pages = data.query.pages;
  const page = Object.values(pages)[0];

  if (!page || page.missing !== undefined || !page.extract) {
    return [];
  }

  const text = page.extract;
  return parseTextToQuestions(text, topic, count);
}

/* ---- Parse Wikipedia text into questions ---- */
function parseTextToQuestions(text, topic, count) {
  const questions = [];

  // Split into sentences
  const sentences = text
    .replace(/\\n+/g, ' ')
    .split(/(?\u003c=[.!?])\\s+/)
    .filter(s => s.length > 40 && s.length < 300)
    .filter(s => !s.startsWith('==') && !s.match(/^\\d+$/));

  // Strategy 1: Fill-in-the-blank (remove key noun from sentence)
  sentences.slice(0, Math.ceil(count * 0.4)).forEach(sentence => {
    const words = sentence.split(' ');
    // Find a capitalized word (likely a proper noun / key term)
    const keyWordIdx = words.findIndex((w, i) => i > 0 && /^[A-Z][a-z]{3,}/.test(w) && !['The','This','That','These','Those','When','Where','While','Although'].includes(w));

    if (keyWordIdx > -1) {
      const keyWord = words[keyWordIdx].replace(/[.,;:]$/, '');
      const blank = sentence.replace(words[keyWordIdx], '______');
      questions.push({
        id: genId('q'),
        type: 'fillinblank',
        questionText: `Fill in the blank: \"${blank}\"`,
        options: [],
        correctAnswer: keyWord,
        explanation: `From Wikipedia: ${sentence}`
      });
    }
  });

  // Strategy 2: True/False — alter a sentence slightly
  sentences.slice(Math.ceil(count * 0.4), Math.ceil(count * 0.7)).forEach(sentence => {
    const isTrue = Math.random() > 0.5;
    let questionSentence = sentence;

    if (!isTrue) {
      // Flip numbers or replace key words with plausible alternatives
      questionSentence = flipFact(sentence);
    }

    questions.push({
      id: genId('q'),
      type: 'truefalse',
      questionText: `True or False: \"${questionSentence}\"`,
      options: ['True', 'False'],
      correctAnswer: isTrue ? 'True' : 'False',
      explanation: `Original: ${sentence}`
    });
  });

  // Strategy 3: "What is X known for?" MCQ
  if (sentences.length > 0) {
    const firstSentence = sentences[0];
    questions.push({
      id: genId('q'),
      type: 'mcq',
      questionText: `According to general knowledge, what is \"${topic}\" primarily associated with?`,
      options: generateDistractors(topic, firstSentence),
      correctAnswer: extractKeyPhrase(firstSentence, topic),
      explanation: firstSentence
    });
  }

  return questions.filter(q => q.questionText && q.correctAnswer).slice(0, count);
}

/* ---- Helper: Extract key phrase from sentence ---- */
function extractKeyPhrase(sentence, topic) {
  // Take the main predicate after "is" or "was"
  const match = sentence.match(/(?:is|was|are|were)\\s+(?:a|an|the)?\\s*([^,.]{3,40})/i);
  if (match) return match[1].trim();
  // Fallback: take first noun phrase
  const words = sentence.split(' ');
  return words.slice(1, 5).join(' ');
}

/* ---- Helper: Flip a fact to make it false ---- */
function flipFact(sentence) {
  // Replace numbers
  let flipped = sentence.replace(/\\b(\\d+)\\b/, m => String(parseInt(m) + (Math.random() > 0.5 ? 1 : -1) * Math.floor(Math.random() * 10 + 1)));
  if (flipped !== sentence) return flipped;

  // Replace known direction/superlative words
  const flips = {
    'largest': 'smallest', 'smallest': 'largest',
    'first': 'last', 'last': 'first',
    'north': 'south', 'south': 'north',
    'east': 'west', 'west': 'east',
    'oldest': 'youngest', 'youngest': 'oldest',
    'highest': 'lowest', 'lowest': 'highest',
    'most': 'least', 'least': 'most',
    'capital': 'city'
  };
  for (const [from, to] of Object.entries(flips)) {
    if (sentence.toLowerCase().includes(from)) {
      return sentence.replace(new RegExp(from, 'i'), to);
    }
  }
  return sentence; // return unchanged if nothing flipped (will be marked as "True")
}

/* ---- Helper: Generate plausible wrong answers ---- */
function generateDistractors(topic, sentence) {
  const correct = extractKeyPhrase(sentence, topic);
  const distractors = [
    correct,
    `A form of entertainment`,
    `A scientific theory`,
    `A geographical location`
  ];
  return shuffle(distractors).slice(0, 4);
}

/* ---- Fallback questions if everything fails ---- */
function generateFallbackQuestions(topic) {
  return [
    {
      id: genId('q'), type: 'mcq',
      questionText: `What best describes \"${topic}\"?`,
      options: ['A concept or subject of study', 'A type of food', 'A musical instrument', 'A form of currency'],
      correctAnswer: 'A concept or subject of study',
      explanation: `This is a placeholder question about ${topic}. Edit it in the admin panel.`
    },
    {
      id: genId('q'), type: 'truefalse',
      questionText: `True or False: \"${topic}\" is a recognized topic of general knowledge.`,
      options: ['True', 'False'],
      correctAnswer: 'True',
      explanation: `Placeholder question for topic: ${topic}`
    }
  ];
}

/* ---- Utility: shuffle array ---- */
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

