// XP & Duolingo-style Achievements Engine
function calculateXPForScore(s) {
  const correctXP = (s.score || 0) * 15;
  const completionXP = 20;
  const pct = Math.round(((s.score || 0) / (s.totalQuestions || 1)) * 100);
  const perfectXP = pct === 100 ? 50 : (pct >= 80 ? 25 : 0);
  const avgTime = (s.timeTaken || 999) / (s.totalQuestions || 1);
  const speedXP = avgTime < 15 ? 20 : 0;
  return correctXP + completionXP + perfectXP + speedXP;
}

function submitScore(scoreEntry) {
  const db = getDB();
  const xpGained = calculateXPForScore(scoreEntry);
  const entry = { ...scoreEntry, xpEarned: xpGained };
  db.scores.push(entry);
  saveDB(db);
  return { xpGained, achievements: getUserAchievements(scoreEntry.userId).unlocked };
}

function getUserXPAndLevel(userId) {
  const db = getDB();
  const scores = db.scores.filter(s => s.userId === userId);
  const totalXP = scores.reduce((sum, s) => sum + (s.xpEarned || calculateXPForScore(s)), 0);

  const levels = [
    { level: 1, name: "Novice Quizzer 🐣", minXP: 0, maxXP: 100 },
    { level: 2, name: "Apprentice ⚡", minXP: 100, maxXP: 250 },
    { level: 3, name: "Scholar 🎓", minXP: 250, maxXP: 500 },
    { level: 4, name: "Expert 🧠", minXP: 500, maxXP: 1000 },
    { level: 5, name: "Master 👑", minXP: 1000, maxXP: 2000 },
    { level: 6, name: "Grandmaster Legend 🚀", minXP: 2000, maxXP: 5000 }
  ];

  let currentLvl = levels[0];
  for (let i = 0; i < levels.length; i++) {
    if (totalXP >= levels[i].minXP) currentLvl = levels[i];
  }

  const nextLvl = levels.find(l => l.level === currentLvl.level + 1) || currentLvl;
  const xpInCurrentLvl = totalXP - currentLvl.minXP;
  const xpForNextLvl = nextLvl.minXP - currentLvl.minXP || 1;
  const progressPct = Math.min(100, Math.round((xpInCurrentLvl / xpForNextLvl) * 100));

  return {
    totalXP,
    level: currentLvl.level,
    levelTitle: currentLvl.name,
    progressPct,
    nextLvlXP: nextLvl.minXP
  };
}

function getUserAchievements(userId) {
  const db = getDB();
  const scores = db.scores.filter(s => s.userId === userId);
  const totalCorrect = scores.reduce((sum, s) => sum + s.score, 0);
  const totalXP = scores.reduce((sum, s) => sum + (s.xpEarned || calculateXPForScore(s)), 0);

  const categories = new Set(scores.map(s => (s.quizCategory || '').toLowerCase()));
  const hasPerfect = scores.some(s => Math.round((s.score / s.totalQuestions) * 100) === 100);
  const hasSpeed = scores.some(s => (s.timeTaken / s.totalQuestions) < 15);

  const allAchievements = [
    { id: 'ach-1', icon: '🚀', title: 'First Step', desc: 'Complete your first quiz', unlocked: scores.length >= 1, progress: `${Math.min(1, scores.length)}/1` },
    { id: 'ach-2', icon: '💯', title: 'Perfectionist', desc: 'Score 100% on any quiz', unlocked: hasPerfect, progress: hasPerfect ? '1/1' : '0/1' },
    { id: 'ach-3', icon: '⚡', title: 'Speed Demon', desc: 'Average less than 15s per question', unlocked: hasSpeed, progress: hasSpeed ? '1/1' : '0/1' },
    { id: 'ach-4', icon: '🎯', title: 'Sharpshooter', desc: 'Answer 20 questions correctly overall', unlocked: totalCorrect >= 20, progress: `${Math.min(20, totalCorrect)}/20` },
    { id: 'ach-5', icon: '📚', title: 'Knowledge Explorer', desc: 'Take quizzes in 3 different subjects', unlocked: categories.size >= 3, progress: `${Math.min(3, categories.size)}/3` },
    { id: 'ach-6', icon: '🔥', title: 'Quiz Enthusiast', desc: 'Complete at least 5 total quizzes', unlocked: scores.length >= 5, progress: `${Math.min(5, scores.length)}/5` },
    { id: 'ach-7', icon: '🎓', title: 'Scholar Status', desc: 'Reach 250 Total XP', unlocked: totalXP >= 250, progress: `${Math.min(250, totalXP)}/250 XP` },
    { id: 'ach-8', icon: '👑', title: 'Grandmaster', desc: 'Reach 1000 Total XP', unlocked: totalXP >= 1000, progress: `${Math.min(1000, totalXP)}/1000 XP` }
  ];

  return {
    unlocked: allAchievements.filter(a => a.unlocked),
    locked: allAchievements.filter(a => !a.unlocked),
    all: allAchievements
  };
}

