190: function calculateXPForScore(s) {
191:   const correctXP = (s.score || 0) * 15;
192:   const completionXP = 20;
193:   const pct = Math.round(((s.score || 0) / (s.totalQuestions || 1)) * 100);
194:   const perfectXP = pct === 100 ? 50 : (pct >= 80 ? 25 : 0);
195:   const avgTime = (s.timeTaken || 999) / (s.totalQuestions || 1);
196:   const speedXP = avgTime < 15 ? 20 : 0;
197:   return correctXP + completionXP + perfectXP + speedXP;
198: }
