/* ---- Import Questions from JSON ---- */
function importQuestionsIntoEditor(e) {
  const file = e.target.files[0];
  if (!file) return;
  if (!file.name.endsWith('.json')) {
    showToast('❌ Only .json files are accepted.', 'error');
    return;
  }
  const reader = new FileReader();
  reader.onload = function(evt) {
    try {
      const data = JSON.parse(evt.target.result);
      const imported = extractQuestionsFromJSON(data);
      if (imported.length === 0) {
        showToast('⚠️ No valid questions found in this JSON file.', 'error');
        return;
      }

      // Auto-fill title/description/category if available and fields are empty
      if (!document.getElementById('quizTitle').value && (data.title || (data.quizzes && data.quizzes[0] && data.quizzes[0].title))) {
        document.getElementById('quizTitle').value = data.title || data.quizzes[0].title;
      }
      if (!document.getElementById('quizDesc').value && (data.description || (data.quizzes && data.quizzes[0] && data.quizzes[0].description))) {
        document.getElementById('quizDesc').value = data.description || data.quizzes[0].description;
      }

      questions = [...questions, ...imported];
      renderAllQuestions();
      showToast(`✅ ${imported.length} questions imported into quiz editor!`, 'success');
      document.getElementById('qEditorWrap').scrollIntoView({ behavior: 'smooth', block: 'start' });
    } catch(err) {
      showToast('❌ Invalid JSON file: ' + err.message, 'error');
    }
  };
  reader.readAsText(file);
  e.target.value = '';
}

function extractQuestionsFromJSON(data) {
  let raw = [];
  if (data.quizzes && Array.isArray(data.quizzes)) {
    data.quizzes.forEach(qz => (qz.questions || []).forEach(q => raw.push(q)));
  } else if (data.questions && Array.isArray(data.questions)) {
    raw = data.questions;
  } else if (Array.isArray(data)) {
    raw = data;
  }

  return raw.map((q, i) => {
    const q_text = q.questionText || q.question || q.text || q.q || '';
    const rawType = (q.type || 'mcq').toLowerCase();
    let type = 'mcq';
    if (rawType.includes('true') || rawType.includes('tf') || rawType.includes('bool')) type = 'truefalse';
    else if (rawType.includes('fill') || rawType.includes('blank')) type = 'fillinblank';

    const opts = q.options || (type === 'truefalse' ? ['True','False'] : ['','','','']);

    let corr = '';
    if (q.correctAnswer !== undefined) {
      corr = q.correctAnswer;
    } else if (q.correct !== undefined) {
      if (typeof q.correct === 'number' && opts.length > 0) {
        corr = opts[q.correct] || '';
      } else {
        corr = String(q.correct);
      }
    } else if (q.answer !== undefined) {
      corr = String(q.answer);
    }

    return {
      id: genId('q'),
      type,
      questionText: q_text,
      options: opts,
      correctAnswer: corr,
      explanation: q.explanation || q.hint || '',
      imageId: q.imageId || ''
    };
  }).filter(q => q.questionText.trim() !== '');
}

