62: // Migrate old quiz format (question/correct-index) to new format (questionText/correctAnswer-string)
63: function migrateQuizzes(quizzes) {
64:   return quizzes.map(quiz => {
65:     const qs = (quiz.questions || []).map(q => {
66:       // Already new format
67:       if (q.questionText !== undefined) return q;
68:       // Old format: convert question -> questionText, correct (index) -> correctAnswer (string)
69:       const newQ = { ...q };
70:       if (q.question !== undefined) {
71:         newQ.questionText = q.question;
72:         delete newQ.question;
73:       }
74:       if (q.correct !== undefined && q.options) {
75:         newQ.correctAnswer = q.options[q.correct] || '';
76:         delete newQ.correct;
77:       }
78:       return newQ;
79:     });
80:     return { ...quiz, questions: qs };
81:   });
82: }
