// admin.js – handles quiz creation and storage in localStorage
document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('quizForm');
  const addBtn = document.getElementById('addQuestionBtn');
  const container = document.getElementById('questionsContainer');
  const template = document.getElementById('questionTemplate');
  const status = document.getElementById('statusMsg');

  const addQuestion = () => {
    const clone = template.content.cloneNode(true);
    container.appendChild(clone);
  };

  // initial one question
  addQuestion();

  addBtn.addEventListener('click', addQuestion);

  // delegate remove button clicks
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('removeQuestion')) {
      e.target.closest('.questionBlock').remove();
    }
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const title = document.getElementById('title').value.trim();
    const category = document.getElementById('category').value.trim();
    const qBlocks = container.querySelectorAll('.questionBlock');
    const questions = [];
    qBlocks.forEach((block) => {
      const qText = block.querySelector('.qText').value.trim();
      const optA = block.querySelector('.optA').value.trim();
      const optB = block.querySelector('.optB').value.trim();
      const optC = block.querySelector('.optC').value.trim();
      const optD = block.querySelector('.optD').value.trim();
      const correct = block.querySelector('.correct').value.trim().toUpperCase();
      questions.push({ qText, options: { A: optA, B: optB, C: optC, D: optD }, correct });
    });
    const newQuiz = { title, category, questions };
    // store in localStorage under "adminAddedQuizzes"
    const existing = JSON.parse(localStorage.getItem('adminAddedQuizzes') || '[]');
    existing.push(newQuiz);
    localStorage.setItem('adminAddedQuizzes', JSON.stringify(existing));
    status.textContent = 'Quiz saved locally. It will appear for all users after the next sync.';
    form.reset();
    container.innerHTML = '<h3>Questions</h3>';
    addQuestion();
  });
});

