function loadQuizzes() {
  // Remote quizzes (static file shipped with the site)
  return fetch('data/quizzes.json')
    .then((resp) => resp.ok ? resp.json() : [])
    .then((remoteQuizzes) => {
      const adminQuizzes = JSON.parse(localStorage.getItem('adminAddedQuizzes') || '[]');
      // Ensure unique IDs – if not present, generate a simple timestamp based id
      const all = remoteQuizzes.concat(adminQuizzes.map((q) => {
        if (!q.id) q.id = 'admin_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5);
        return q;
      }));
      return all;
    })
    .catch((err) => {
      console.error('Failed to load quizzes', err);
      return [];
    });
}

