let _cachedQuizzes = null;

/**
 * Get all quizzes with caching for fast access
 */
function getAllQuizzes() {
  if (_cachedQuizzes) return _cachedQuizzes;
  const db = getDB();
  _cachedQuizzes = db.quizzes || [];
  return _cachedQuizzes;
}

/**
 * Retrieve a single quiz by ID using cached data
 */
function getQuizById(id) {
  const quizzes = getAllQuizzes();
  return quizzes.find(q => q.id === id);
}

