/* ================================================
   style.css — Global Design System
   Created by A.SHAM SHARAN
   ================================================ */

@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800;900&family=Inter:wght@300;400;500;600;700&display=swap');

/* ---- CSS Variables ---- */
:root {
  --bg-primary: #06060f;
  --bg-secondary: #0d0d1a;
  --bg-card: #111128;
  --bg-card-hover: #161630;
  --bg-glass: rgba(17, 17, 40, 0.7);

  --accent-blue: #6366f1;
  --accent-purple: #8b5cf6;
  --accent-emerald: #10b981;
  --accent-amber: #f59e0b;
  --accent-rose: #f43f5e;
  --accent-cyan: #06b6d4;

  --gradient-main: linear-gradient(135deg, #6366f1, #8b5cf6);
  --gradient-text: linear-gradient(135deg, #6366f1, #a78bfa, #06b6d4);
  --gradient-emerald: linear-gradient(135deg, #10b981, #06b6d4);
  --gradient-amber: linear-gradient(135deg, #f59e0b, #f97316);

  --text-primary: #f0f0ff;
  --text-secondary: #9898c0;
  --text-muted: #5a5a7a;

  --border-color: rgba(99, 102, 241, 0.15);
  --border-hover: rgba(99, 102, 241, 0.4);

  --shadow-card: 0 4px 24px rgba(0,0,0,0.4);
  --shadow-glow: 0 0 30px rgba(99, 102, 241, 0.2);
  --shadow-glow-strong: 0 0 50px rgba(99, 102, 241, 0.35);

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --radius-full: 9999px;

  --transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ---- Reset & Base ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  min-height: 100vh;
  overflow-x: hidden;
  line-height: 1.6;
}

a { text-decoration: none; color: inherit; }
code { font-family: monospace; background: rgba(99,102,241,0.15); padding: 2px 6px; border-radius: 4px; font-size: 0.85em; }
img { max-width: 100%; }

/* ---- Animated Background ---- */
.bg-orbs {
  position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  pointer-events: none; z-index: 0; overflow: hidden;
}
.orb {
  position: absolute; border-radius: 50%;
  filter: blur(80px); opacity: 0.12;
  animation: orbFloat 20s ease-in-out infinite;
}
.orb-1 { width: 600px; height: 600px; background: var(--accent-blue); top: -200px; left: -150px; animation-delay: 0s; }
.orb-2 { width: 500px; height: 500px; background: var(--accent-purple); bottom: -100px; right: -100px; animation-delay: -7s; }
.orb-3 { width: 400px; height: 400px; background: var(--accent-cyan); top: 40%; left: 50%; animation-delay: -14s; }

@keyframes orbFloat {
  0%, 100% { transform: translate(0,0) scale(1); }
  33% { transform: translate(30px,-30px) scale(1.05); }
  66% { transform: translate(-20px,20px) scale(0.95); }
}

/* ---- Navbar ---- */
.navbar {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  padding: 1rem 0;
  transition: var(--transition);
  border-bottom: 1px solid transparent;
}
.navbar.scrolled {
  background: var(--bg-glass);
  backdrop-filter: blur(20px);
  border-bottom-color: var(--border-color);
  box-shadow: 0 4px 30px rgba(0,0,0,0.3);
}
.nav-container {
  max-width: 1200px; margin: 0 auto;
  padding: 0 2rem;
  display: flex; align-items: center; justify-content: space-between;
}
.nav-logo {
  display: flex; align-items: center; gap: 0.5rem;
  font-family: 'Outfit', sans-serif; font-weight: 800; font-size: 1.5rem;
  transition: var(--transition);
}
.nav-logo:hover { transform: scale(1.04); }
.logo-icon { font-size: 1.6rem; }
.logo-text .accent { background: var(--gradient-text); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }

.nav-links { display: flex; align-items: center; gap: 0.5rem; }
.nav-link {
  padding: 0.5rem 1rem; border-radius: var(--radius-full);
  color: var(--text-secondary); font-size: 0.95rem; font-weight: 500;
  transition: var(--transition);
}
.nav-link:hover, .nav-link.active { color: var(--text-primary); background: rgba(99,102,241,0.12); }

.nav-auth { display: flex; gap: 0.5rem; margin-left: 1rem; }
.nav-user { position: relative; margin-left: 1rem; }
.user-menu {
  display: flex; align-items: center; gap: 0.5rem;
  padding: 0.4rem 1rem 0.4rem 0.4rem;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-color);
  cursor: pointer; transition: var(--transition);
}
.user-menu:hover { border-color: var(--border-hover); background: rgba(99,102,241,0.08); }
.user-avatar {
  width: 32px; height: 32px; border-radius: 50%;
