  cursor: pointer; transition: var(--transition); color: var(--text-muted);
}
.auth-tab.active { background: var(--gradient-main); color: #fff; box-shadow: 0 2px 10px rgba(99,102,241,0.3); }
.auth-title { font-family: 'Outfit', sans-serif; font-size: 1.6rem; font-weight: 800; margin-bottom: 0.3rem; }
.auth-subtitle { color: var(--text-muted); font-size: 0.9rem; margin-bottom: 1.8rem; }

/* ---- Alerts / Toast ---- */
.toast {
  position: fixed; bottom: 2rem; right: 2rem; z-index: 9999;
  padding: 1rem 1.5rem; border-radius: var(--radius-md);
  font-weight: 600; font-size: 0.95rem;
  animation: toastIn 0.3s ease;
  max-width: 350px;
}
@keyframes toastIn { from { opacity: 0; transform: translateY(20px) scale(0.95); } to { opacity: 1; transform: translateY(0) scale(1); } }
.toast-success { background: rgba(16,185,129,0.15); border: 1px solid rgba(16,185,129,0.4); color: #6ee7b7; }
.toast-error { background: rgba(244,63,94,0.15); border: 1px solid rgba(244,63,94,0.4); color: #fda4af; }
.toast-info { background: rgba(99,102,241,0.15); border: 1px solid rgba(99,102,241,0.4); color: #a5b4fc; }

/* ---- Quiz Player ---- */
.quiz-page { min-height: 100vh; padding: 7rem 1rem 3rem; max-width: 800px; margin: 0 auto; position: relative; z-index: 1; }
.quiz-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 2rem; flex-wrap: wrap; gap: 1rem; }
.quiz-progress-wrap { flex: 1; }
.quiz-progress-info { display: flex; justify-content: space-between; font-size: 0.85rem; color: var(--text-muted); margin-bottom: 0.5rem; }
.progress-bar-outer { height: 6px; background: rgba(99,102,241,0.15); border-radius: 3px; overflow: hidden; }
.progress-bar-inner { height: 100%; background: var(--gradient-main); border-radius: 3px; transition: width 0.5s ease; }

/* Timer */
.timer-wrap { position: relative; width: 64px; height: 64px; flex-shrink: 0; }
.timer-svg { width: 64px; height: 64px; transform: rotate(-90deg); }
.timer-bg { fill: none; stroke: rgba(99,102,241,0.15); stroke-width: 4; }
.timer-ring { fill: none; stroke-width: 4; stroke-linecap: round; transition: stroke 0.5s ease; }
.timer-text {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-family: 'Outfit', sans-serif; font-weight: 700; font-size: 1rem;
}

/* Question Card */
.question-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-xl); padding: 2rem;
  box-shadow: var(--shadow-card); margin-bottom: 1.5rem;
  animation: fadeSlideIn 0.4s ease;
}
.question-type-badge {
  display: inline-block; padding: 0.25rem 0.7rem; border-radius: var(--radius-full);
  font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px;
  background: rgba(99,102,241,0.12); color: var(--accent-blue);
  margin-bottom: 1rem;
}
.question-text { font-family: 'Outfit', sans-serif; font-size: 1.2rem; font-weight: 700; margin-bottom: 1.5rem; line-height: 1.5; }

.options-grid { display: flex; flex-direction: column; gap: 0.75rem; }
.option-btn {
  padding: 1rem 1.25rem; border-radius: var(--radius-md);
  border: 1px solid var(--border-color); background: rgba(255,255,255,0.03);
  color: var(--text-primary); font-size: 0.95rem; font-weight: 500;
  cursor: pointer; transition: var(--transition); text-align: left;
  display: flex; align-items: center; gap: 0.8rem;
}
.option-btn:hover:not(:disabled) { border-color: var(--border-hover); background: rgba(99,102,241,0.08); transform: translateX(4px); }
.option-btn.correct { background: rgba(16,185,129,0.12); border-color: rgba(16,185,129,0.5); color: #6ee7b7; animation: pulseGreen 0.5s ease; }
.option-btn.incorrect { background: rgba(244,63,94,0.12); border-color: rgba(244,63,94,0.5); color: #fda4af; animation: shakeX 0.4s ease; }
.option-btn:disabled { cursor: not-allowed; }
.option-letter {
  width: 28px; height: 28px; border-radius: 50%;
  background: rgba(99,102,241,0.15); display: flex; align-items: center; justify-content: center;
  font-size: 0.8rem; font-weight: 700; flex-shrink: 0;
}

.fill-input-wrap { display: flex; gap: 0.75rem; }
.fill-input-wrap .form-input { flex: 1; }

.explanation-box {
  margin-top: 1rem; padding: 1rem;
  background: rgba(16,185,129,0.08); border: 1px solid rgba(16,185,129,0.25);
  border-radius: var(--radius-md); font-size: 0.9rem; color: var(--text-secondary);
}
.explanation-box strong { color: var(--accent-emerald); }

/* ---- Result Screen ---- */
.result-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-xl); padding: 2.5rem; text-align: center;
  box-shadow: var(--shadow-glow); animation: fadeSlideIn 0.5s ease;
}
.result-score-ring {
  width: 140px; height: 140px; margin: 0 auto 1.5rem;
  position: relative; display: flex; align-items: center; justify-content: center;
}
.result-score-svg { width: 140px; height: 140px; transform: rotate(-90deg); position: absolute; }
.score-bg { fill: none; stroke: rgba(99,102,241,0.15); stroke-width: 8; }
.score-fill { fill: none; stroke-width: 8; stroke-linecap: round; transition: stroke-dashoffset 1.5s cubic-bezier(0.4,0,0.2,1); }
.score-text-inner { font-family: 'Outfit', sans-serif; font-size: 2rem; font-weight: 900; }
.result-grade {
  font-size: 1.5rem; font-weight: 800; font-family: 'Outfit', sans-serif;
  margin-bottom: 0.5rem;
}
.result-title { font-family: 'Outfit', sans-serif; font-size: 1.8rem; font-weight: 900; margin-bottom: 0.5rem; }
.result-subtitle { color: var(--text-secondary); margin-bottom: 2rem; }
.result-stats { display: flex; justify-content: center; gap: 2rem; margin-bottom: 2rem; flex-wrap: wrap; }
.result-stat { text-align: center; }
.result-stat-num { font-family: 'Outfit', sans-serif; font-size: 1.5rem; font-weight: 800; }
.result-stat-label { font-size: 0.8rem; color: var(--text-muted); }
.result-actions { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }

/* ---- Leaderboard ---- */
.lb-page { min-height: 100vh; padding: 7rem 1rem 3rem; max-width: 900px; margin: 0 auto; position: relative; z-index: 1; }
.lb-table { width: 100%; border-collapse: collapse; }
.lb-table thead th {
  padding: 1rem 1.2rem; text-align: left;
  font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.5px;
  color: var(--text-muted); font-weight: 600;
  border-bottom: 1px solid var(--border-color);
}
.lb-row { transition: var(--transition); }
.lb-row td { padding: 1rem 1.2rem; border-bottom: 1px solid rgba(99,102,241,0.06); font-size: 0.95rem; }
.lb-row:hover td { background: rgba(99,102,241,0.04); }
.lb-rank { font-family: 'Outfit', sans-serif; font-weight: 800; font-size: 1.1rem; }
.rank-gold { color: #fbbf24; }
.rank-silver { color: #94a3b8; }
.rank-bronze { color: #b45309; }
.lb-user { display: flex; align-items: center; gap: 0.75rem; }
.lb-avatar {
  width: 36px; height: 36px; border-radius: 50%;
  background: var(--gradient-main);
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 0.85rem; flex-shrink: 0;
}
.lb-score { font-weight: 700; color: var(--accent-blue); }

/* ---- Admin Layout ---- */
.admin-layout { display: flex; min-height: 100vh; }
.admin-sidebar {
  width: 240px; flex-shrink: 0;
  background: var(--bg-secondary); border-right: 1px solid var(--border-color);
  padding: 5rem 1rem 1rem; position: fixed; top: 0; left: 0; height: 100%;
  overflow-y: auto; z-index: 100;
}
.sidebar-nav { display: flex; flex-direction: column; gap: 0.25rem; }
.sidebar-link {
  display: flex; align-items: center; gap: 0.7rem;
  padding: 0.75rem 1rem; border-radius: var(--radius-md);
  color: var(--text-secondary); font-size: 0.9rem; font-weight: 500;
  transition: var(--transition); cursor: pointer;
}
.sidebar-link:hover, .sidebar-link.active { background: rgba(99,102,241,0.12); color: var(--text-primary); }
.sidebar-link.active { background: rgba(99,102,241,0.15); color: var(--accent-blue); }
.sidebar-label { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; color: var(--text-muted); padding: 1rem 1rem 0.25rem; font-weight: 600; }

.admin-main { margin-left: 240px; flex: 1; padding: 5.5rem 2rem 2rem; }
.admin-page-header { margin-bottom: 2rem; }
.admin-page-title { font-family: 'Outfit', sans-serif; font-size: 1.8rem; font-weight: 800; }
.admin-page-sub { color: var(--text-muted); margin-top: 0.25rem; }

.stats-row { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 1rem; margin-bottom: 2rem; }
.stat-box {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 1.3rem 1.5rem;
}
.stat-box-num { font-family: 'Outfit', sans-serif; font-size: 2rem; font-weight: 900; }
.stat-box-label { font-size: 0.8rem; color: var(--text-muted); margin-top: 0.2rem; }
.stat-box-blue .stat-box-num { color: var(--accent-blue); }
.stat-box-green .stat-box-num { color: var(--accent-emerald); }
.stat-box-purple .stat-box-num { color: var(--accent-purple); }
.stat-box-amber .stat-box-num { color: var(--accent-amber); }

/* ---- Tables (Admin) ---- */
.table-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); overflow: hidden;
}
.table-header { padding: 1.2rem 1.5rem; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--border-color); }
.table-title { font-family: 'Outfit', sans-serif; font-weight: 700; font-size: 1rem; }
.data-table { width: 100%; border-collapse: collapse; }
.data-table thead th { padding: 0.9rem 1.2rem; text-align: left; font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.5px; color: var(--text-muted); background: rgba(99,102,241,0.04); border-bottom: 1px solid var(--border-color); }
.data-table tbody td { padding: 1rem 1.2rem; border-bottom: 1px solid rgba(99,102,241,0.05); font-size: 0.9rem; }
.data-table tbody tr:last-child td { border-bottom: none; }
.data-table tbody tr:hover td { background: rgba(99,102,241,0.03); }
.action-btns { display: flex; gap: 0.5rem; }

/* ---- Question Editor (Admin) ---- */
.question-editor {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 1.5rem; margin-bottom: 1rem;
  position: relative;
}
.q-editor-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 1.2rem; }
.q-editor-num { font-weight: 700; color: var(--accent-blue); font-size: 0.9rem; }
.option-row { display: flex; gap: 0.5rem; margin-bottom: 0.5rem; align-items: center; }
.correct-radio { width: 18px; height: 18px; accent-color: var(--accent-emerald); cursor: pointer; flex-shrink: 0; }

/* ---- Page Helpers ---- */
.page-wrap { min-height: 100vh; padding: 7rem 1rem 3rem; max-width: 1100px; margin: 0 auto; position: relative; z-index: 1; }
.page-header { margin-bottom: 2rem; }
.page-title { font-family: 'Outfit', sans-serif; font-size: 2rem; font-weight: 800; margin-bottom: 0.3rem; }
.page-sub { color: var(--text-muted); }

.filter-bar { display: flex; gap: 0.75rem; flex-wrap: wrap; margin-bottom: 2rem; }
.filter-btn {
  padding: 0.4rem 1rem; border-radius: var(--radius-full);
  border: 1px solid var(--border-color); background: rgba(99,102,241,0.06);
  color: var(--text-secondary); font-size: 0.85rem; font-weight: 500;
  cursor: pointer; transition: var(--transition);
}
.filter-btn:hover, .filter-btn.active { border-color: var(--accent-blue); color: var(--accent-blue); background: rgba(99,102,241,0.12); }

.search-wrap { position: relative; margin-bottom: 1.5rem; max-width: 400px; }
.search-icon { position: absolute; left: 1rem; top: 50%; transform: translateY(-50%); color: var(--text-muted); pointer-events: none; }
.search-input { padding-left: 2.8rem !important; }

/* ---- Empty State ---- */
.empty-state {
  text-align: center; padding: 3rem; color: var(--text-muted);
  grid-column: 1/-1; font-size: 0.95rem;
}
.empty-state a { color: var(--accent-blue); text-decoration: underline; }

/* ---- Modal ---- */
.modal-overlay {
  position: fixed; inset: 0; z-index: 2000;
  background: rgba(0,0,0,0.7); backdrop-filter: blur(4px);
  display: flex; align-items: center; justify-content: center; padding: 1rem;
  animation: fadeIn 0.2s ease;
}
.modal {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-xl); padding: 2rem; width: 100%; max-width: 500px;
  box-shadow: var(--shadow-glow-strong); animation: fadeSlideIn 0.3s ease;
}
.modal-title { font-family: 'Outfit', sans-serif; font-size: 1.4rem; font-weight: 800; margin-bottom: 1.5rem; }
.modal-actions { display: flex; gap: 0.75rem; justify-content: flex-end; margin-top: 1.5rem; }

/* ---- Badges ---- */
.badge {
  display: inline-flex; align-items: center; padding: 0.25rem 0.65rem;
  border-radius: var(--radius-full); font-size: 0.75rem; font-weight: 600;
}
.badge-blue { background: rgba(99,102,241,0.15); color: var(--accent-blue); }
.badge-green { background: rgba(16,185,129,0.15); color: var(--accent-emerald); }
.badge-amber { background: rgba(245,158,11,0.15); color: var(--accent-amber); }
.badge-rose { background: rgba(244,63,94,0.15); color: var(--accent-rose); }
.badge-purple { background: rgba(139,92,246,0.15); color: var(--accent-purple); }

/* ---- Footer ---- */
.footer { border-top: 1px solid var(--border-color); padding: 3rem 0 1.5rem; position: relative; z-index: 1; }
.footer-content { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1.5rem; margin-bottom: 2rem; }
.footer-brand { display: flex; flex-direction: column; gap: 0.4rem; }
.footer-brand p { color: var(--text-muted); font-size: 0.88rem; margin-top: 0.3rem; }
.footer-links { display: flex; gap: 1.5rem; flex-wrap: wrap; }
.footer-links a { color: var(--text-muted); font-size: 0.88rem; transition: var(--transition); }
.footer-links a:hover { color: var(--accent-blue); }
.footer-bottom { text-align: center; padding-top: 1.5rem; border-top: 1px solid var(--border-color); }
.footer-bottom p { color: var(--text-muted); font-size: 0.82rem; }

/* ---- Animations ---- */
@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes pulseGreen {
  0% { box-shadow: 0 0 0 0 rgba(16,185,129,0.5); }
  70% { box-shadow: 0 0 0 8px rgba(16,185,129,0); }
  100% { box-shadow: 0 0 0 0 rgba(16,185,129,0); }
}
@keyframes shakeX {
  0%, 100% { transform: translateX(0); }
  20%, 60% { transform: translateX(-6px); }
  40%, 80% { transform: translateX(6px); }
}
.animate-in { animation: fadeSlideIn 0.5s ease both; }

/* ---- Utility ---- */
.hidden { display: none !important; }
.flex { display: flex; }
.items-center { align-items: center; }
.gap-1 { gap: 0.5rem; }
.mt-1 { margin-top: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.text-muted { color: var(--text-muted); }
.text-accent { color: var(--accent-blue); }
.w-full { width: 100%; }
.divider { height: 1px; background: var(--border-color); margin: 1.5rem 0; }

/* ---- Responsive ---- */
@media (max-width: 900px) {
  .hero { flex-direction: column; text-align: center; padding-top: 6rem; gap: 2rem; }
  .hero-desc { margin: 0 auto 2rem; }
  .hero-actions { justify-content: center; }
  .hero-stats { justify-content: center; }
  .hero-visual { width: 100%; max-width: 360px; margin: 0 auto; }
  .admin-sidebar { transform: translateX(-100%); transition: transform 0.3s ease; }
  .admin-sidebar.open { transform: translateX(0); }
  .admin-main { margin-left: 0; }
}
@media (max-width: 600px) {
  .nav-links { display: none; flex-direction: column; position: absolute; top: 100%; left: 0; right: 0; background: var(--bg-secondary); border-bottom: 1px solid var(--border-color); padding: 1rem; gap: 0.3rem; }
  .nav-links.open { display: flex; }
  .hamburger { display: block; }
  .quiz-grid { grid-template-columns: 1fr; }
  .hero-title { font-size: 2rem; }
  .result-stats { gap: 1rem; }
  .filter-bar { gap: 0.5rem; }
}

/* ================================================
   style.css — Global Design System
   Created by A.SHAM SHARAN
   ================================================ */

@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800;900&family=Inter:wght@300;400;500;600;700&display=swap');

/* ---- CSS Variables ---- */
:root {
  --bg-primary: #06060f;
  --bg-secondary: #0d0d1a;
  --bg-card: #111128;
  --bg-card-hover: #161630;
  --bg-glass: rgba(17, 17, 40, 0.7);

  --accent-blue: #6366f1;
  --accent-purple: #8b5cf6;
  --accent-emerald: #10b981;
  --accent-amber: #f59e0b;
  --accent-rose: #f43f5e;
  --accent-cyan: #06b6d4;

  --gradient-main: linear-gradient(135deg, #6366f1, #8b5cf6);
  --gradient-text: linear-gradient(135deg, #6366f1, #a78bfa, #06b6d4);
  --gradient-emerald: linear-gradient(135deg, #10b981, #06b6d4);
  --gradient-amber: linear-gradient(135deg, #f59e0b, #f97316);

  --text-primary: #f0f0ff;
  --text-secondary: #9898c0;
  --text-muted: #5a5a7a;

  --border-color: rgba(99, 102, 241, 0.15);
  --border-hover: rgba(99, 102, 241, 0.4);

  --shadow-card: 0 4px 24px rgba(0,0,0,0.4);
  --shadow-glow: 0 0 30px rgba(99, 102, 241, 0.2);
  --shadow-glow-strong: 0 0 50px rgba(99, 102, 241, 0.35);

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --radius-full: 9999px;

  --transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ---- Reset & Base ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  min-height: 100vh;
  overflow-x: hidden;
  line-height: 1.6;
}

a { text-decoration: none; color: inherit; }
code { font-family: monospace; background: rgba(99,102,241,0.15); padding: 2px 6px; border-radius: 4px; font-size: 0.85em; }
img { max-width: 100%; }

/* ---- Animated Background ---- */
.bg-orbs {
  position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  pointer-events: none; z-index: 0; overflow: hidden;
}
.orb {
  position: absolute; border-radius: 50%;
  filter: blur(80px); opacity: 0.12;
  animation: orbFloat 20s ease-in-out infinite;
}
.orb-1 { width: 600px; height: 600px; background: var(--accent-blue); top: -200px; left: -150px; animation-delay: 0s; }
.orb-2 { width: 500px; height: 500px; background: var(--accent-purple); bottom: -100px; right: -100px; animation-delay: -7s; }
.orb-3 { width: 400px; height: 400px; background: var(--accent-cyan); top: 40%; left: 50%; animation-delay: -14s; }

@keyframes orbFloat {
  0%, 100% { transform: translate(0,0) scale(1); }
  33% { transform: translate(30px,-30px) scale(1.05); }
  66% { transform: translate(-20px,20px) scale(0.95); }
}

/* ---- Navbar ---- */
.navbar {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  padding: 1rem 0;
  transition: var(--transition);
  border-bottom: 1px solid transparent;
}
.navbar.scrolled {
  background: var(--bg-glass);
  backdrop-filter: blur(20px);
  border-bottom-color: var(--border-color);
  box-shadow: 0 4px 30px rgba(0,0,0,0.3);
}
.nav-container {
  max-width: 1200px; margin: 0 auto;
  padding: 0 2rem;
  display: flex; align-items: center; justify-content: space-between;
}
.nav-logo {
  display: flex; align-items: center; gap: 0.5rem;
  font-family: 'Outfit', sans-serif; font-weight: 800; font-size: 1.5rem;
  transition: var(--transition);
}
.nav-logo:hover { transform: scale(1.04); }
.logo-icon { font-size: 1.6rem; }
.logo-text .accent { background: var(--gradient-text); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }

.nav-links { display: flex; align-items: center; gap: 0.5rem; }
.nav-link {
  padding: 0.5rem 1rem; border-radius: var(--radius-full);
  color: var(--text-secondary); font-size: 0.95rem; font-weight: 500;
  transition: var(--transition);
}
.nav-link:hover, .nav-link.active { color: var(--text-primary); background: rgba(99,102,241,0.12); }

.nav-auth { display: flex; gap: 0.5rem; margin-left: 1rem; }
.nav-user { position: relative; margin-left: 1rem; }
.user-menu {
  display: flex; align-items: center; gap: 0.5rem;
  padding: 0.4rem 1rem 0.4rem 0.4rem;
  border-radius: var(--radius-full);
  border: 1px solid var(--border-color);
  cursor: pointer; transition: var(--transition);
}
.user-menu:hover { border-color: var(--border-hover); background: rgba(99,102,241,0.08); }
.user-avatar {
  width: 32px; height: 32px; border-radius: 50%;
  background: var(--gradient-main);
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 0.85rem;
}
.chevron { font-size: 0.7rem; color: var(--text-muted); }
.user-dropdown {
  position: absolute; top: calc(100% + 8px); right: 0; min-width: 180px;
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-md); padding: 0.5rem;
  box-shadow: var(--shadow-card);
  animation: dropIn 0.2s ease;
}
@keyframes dropIn { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: translateY(0); } }
.dropdown-item {
  display: block; padding: 0.6rem 1rem; border-radius: var(--radius-sm);
  color: var(--text-secondary); font-size: 0.9rem; cursor: pointer;
  transition: var(--transition);
}
.dropdown-item:hover { background: rgba(99,102,241,0.1); color: var(--text-primary); }

.hamburger { display: none; background: none; border: none; color: var(--text-primary);
  font-size: 1.5rem; cursor: pointer; padding: 0.3rem; }

/* ---- Buttons ---- */
.btn {
  display: inline-flex; align-items: center; gap: 0.5rem;
  padding: 0.55rem 1.3rem; border-radius: var(--radius-full);
  font-size: 0.95rem; font-weight: 600; cursor: pointer;
  transition: var(--transition); border: none; font-family: inherit;
  text-decoration: none;
}
.btn-primary {
  background: var(--gradient-main);
  color: #fff;
  box-shadow: 0 4px 20px rgba(99,102,241,0.35);
}
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 30px rgba(99,102,241,0.5); }
.btn-primary:active { transform: translateY(0); }
.btn-ghost {
  background: rgba(99,102,241,0.08);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
}
.btn-ghost:hover { border-color: var(--border-hover); background: rgba(99,102,241,0.15); transform: translateY(-1px); }
.btn-danger { background: rgba(244, 63, 94, 0.1); border: 1px solid rgba(244,63,94,0.3); color: var(--accent-rose); }
.btn-danger:hover { background: rgba(244,63,94,0.2); }
.btn-success { background: var(--gradient-emerald); color: #fff; box-shadow: 0 4px 20px rgba(16,185,129,0.3); }
.btn-success:hover { transform: translateY(-2px); box-shadow: 0 8px 30px rgba(16,185,129,0.45); }
.btn-lg { padding: 0.8rem 2rem; font-size: 1.05rem; }
.btn-sm { padding: 0.35rem 0.9rem; font-size: 0.82rem; }
.btn-full { width: 100%; justify-content: center; }

/* ---- Hero ---- */
.hero { min-height: 100vh; display: flex; align-items: center; padding: 8rem 2rem 4rem; max-width: 1200px; margin: 0 auto; gap: 4rem; position: relative; z-index: 1; }
.hero-content { flex: 1; max-width: 600px; }
.hero-badge {
  display: inline-flex; align-items: center; gap: 0.5rem;
  padding: 0.4rem 1rem; border-radius: var(--radius-full);
  background: rgba(99,102,241,0.12); border: 1px solid var(--border-color);
  font-size: 0.85rem; color: var(--accent-blue); font-weight: 600;
  margin-bottom: 1.5rem;
  animation: fadeSlideIn 0.6s ease forwards;
}
.hero-title {
  font-family: 'Outfit', sans-serif;
  font-size: clamp(2.5rem, 6vw, 4rem);
  font-weight: 900; line-height: 1.1;
  margin-bottom: 1.2rem;
  animation: fadeSlideIn 0.6s 0.1s ease both;
}
.gradient-text { background: var(--gradient-text); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.hero-desc { color: var(--text-secondary); font-size: 1.1rem; margin-bottom: 2rem; max-width: 480px; animation: fadeSlideIn 0.6s 0.2s ease both; }
.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; margin-bottom: 2.5rem; animation: fadeSlideIn 0.6s 0.3s ease both; }
.hero-stats { display: flex; align-items: center; gap: 1.5rem; animation: fadeSlideIn 0.6s 0.4s ease both; }
.stat-card { text-align: center; }
.stat-num { font-family: 'Outfit', sans-serif; font-size: 2rem; font-weight: 800; background: var(--gradient-text); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.stat-label { font-size: 0.8rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 1px; }
.stat-divider { width: 1px; height: 40px; background: var(--border-color); }

/* Quiz Preview Card */
.hero-visual { flex: 0 0 380px; animation: floatCard 4s ease-in-out infinite; }
@keyframes floatCard { 0%, 100% { transform: translateY(0px); } 50% { transform: translateY(-12px); } }
.quiz-preview-card { background: var(--bg-card); border: 1px solid var(--border-color); border-radius: var(--radius-xl); padding: 1.8rem; box-shadow: var(--shadow-glow-strong); }
.qp-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1.2rem; }
.qp-category { background: rgba(99,102,241,0.15); color: var(--accent-blue); padding: 0.3rem 0.8rem; border-radius: var(--radius-full); font-size: 0.8rem; font-weight: 600; }
.qp-timer { color: var(--accent-amber); font-weight: 600; font-size: 0.9rem; }
.qp-question { font-size: 1.1rem; font-weight: 600; margin-bottom: 1.2rem; }
.qp-options { display: flex; flex-direction: column; gap: 0.6rem; margin-bottom: 1.2rem; }
.qp-opt { padding: 0.65rem 1rem; border-radius: var(--radius-sm); border: 1px solid var(--border-color); font-size: 0.9rem; transition: var(--transition); cursor: pointer; }
.qp-opt.correct { background: rgba(16,185,129,0.15); border-color: rgba(16,185,129,0.4); color: var(--accent-emerald); font-weight: 600; }
.qp-progress { height: 4px; background: rgba(99,102,241,0.15); border-radius: 2px; overflow: hidden; }
.qp-bar { height: 100%; background: var(--gradient-main); border-radius: 2px; transition: width 0.5s ease; }

/* ---- Sections ---- */
.section { padding: 5rem 0; position: relative; z-index: 1; }
.container { max-width: 1200px; margin: 0 auto; padding: 0 2rem; }
.section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 2.5rem; }
.section-title { font-family: 'Outfit', sans-serif; font-size: clamp(1.6rem, 3vw, 2.2rem); font-weight: 800; }
.text-center { text-align: center; }

/* ---- Quiz Grid / Cards ---- */
.quiz-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 1.5rem; }
.quiz-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 1.5rem;
  cursor: pointer; transition: var(--transition-slow);
  position: relative; overflow: hidden;
}
.quiz-card::before { content: ''; position: absolute; inset: 0; background: var(--gradient-main); opacity: 0; transition: var(--transition); }
.quiz-card:hover { border-color: var(--border-hover); transform: translateY(-4px); box-shadow: var(--shadow-glow); }
.quiz-card:hover::before { opacity: 0.04; }

.card-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 1rem; }
.card-category {
  padding: 0.3rem 0.8rem; border-radius: var(--radius-full);
  font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px;
}
.cat-science { background: rgba(6,182,212,0.15); color: var(--accent-cyan); }
.cat-history { background: rgba(245,158,11,0.15); color: var(--accent-amber); }
.cat-geography { background: rgba(16,185,129,0.15); color: var(--accent-emerald); }
.cat-sports { background: rgba(244,63,94,0.15); color: var(--accent-rose); }
.cat-technology { background: rgba(99,102,241,0.15); color: var(--accent-blue); }
.cat-general { background: rgba(139,92,246,0.15); color: var(--accent-purple); }
.cat-default { background: rgba(99,102,241,0.15); color: var(--accent-blue); }

.card-title { font-family: 'Outfit', sans-serif; font-size: 1.1rem; font-weight: 700; margin-bottom: 0.5rem; }
.card-desc { font-size: 0.88rem; color: var(--text-secondary); margin-bottom: 1.2rem; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.card-meta { display: flex; gap: 1rem; font-size: 0.8rem; color: var(--text-muted); }
.card-meta span { display: flex; align-items: center; gap: 0.3rem; }

/* ---- Features Grid ---- */
.features-section { background: linear-gradient(to bottom, transparent, rgba(99,102,241,0.04), transparent); }
.features-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 1.5rem; margin-top: 2.5rem; }
.feature-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 1.8rem;
  transition: var(--transition-slow);
}
.feature-card:hover { border-color: var(--border-hover); transform: translateY(-3px); box-shadow: var(--shadow-card); }
.feature-icon { font-size: 2rem; margin-bottom: 1rem; }
.feature-card h3 { font-family: 'Outfit', sans-serif; font-size: 1.1rem; font-weight: 700; margin-bottom: 0.5rem; }
.feature-card p { font-size: 0.9rem; color: var(--text-secondary); }

/* ---- Forms ---- */
.form-group { margin-bottom: 1.3rem; }
.form-label { display: block; font-size: 0.88rem; font-weight: 600; color: var(--text-secondary); margin-bottom: 0.5rem; }
.form-input, .form-select, .form-textarea {
  width: 100%; padding: 0.75rem 1rem;
  background: rgba(255,255,255,0.04); border: 1px solid var(--border-color);
  border-radius: var(--radius-md); color: var(--text-primary);
  font-size: 0.95rem; font-family: inherit; transition: var(--transition);
  outline: none;
}
.form-input::placeholder, .form-textarea::placeholder { color: var(--text-muted); }
.form-input:focus, .form-select:focus, .form-textarea:focus {
  border-color: var(--accent-blue);
  box-shadow: 0 0 0 3px rgba(99,102,241,0.15);
  background: rgba(255,255,255,0.06);
}
.form-input.error { border-color: var(--accent-rose); }
.form-error { font-size: 0.8rem; color: var(--accent-rose); margin-top: 0.3rem; }
.form-hint { font-size: 0.78rem; color: var(--text-muted); margin-top: 0.3rem; }
.form-select { appearance: none; cursor: pointer; }
.form-textarea { resize: vertical; min-height: 100px; }

/* ---- Auth Page ---- */
.auth-page { min-height: 100vh; display: flex; align-items: center; justify-content: center; padding: 6rem 1rem 2rem; position: relative; z-index: 1; }
.auth-card {
  width: 100%; max-width: 440px;
  background: var(--bg-glass); border: 1px solid var(--border-color);
  border-radius: var(--radius-xl); padding: 2.5rem;
  backdrop-filter: blur(20px);
  box-shadow: var(--shadow-glow);
  animation: fadeSlideIn 0.5s ease;
}
.auth-tabs { display: flex; margin-bottom: 2rem; background: rgba(255,255,255,0.04); border-radius: var(--radius-md); padding: 4px; }
.auth-tab {
  flex: 1; padding: 0.6rem; border-radius: var(--radius-sm);
  text-align: center; font-weight: 600; font-size: 0.9rem;
  cursor: pointer; transition: var(--transition); color: var(--text-muted);
}
.auth-tab.active { background: var(--gradient-main); color: #fff; box-shadow: 0 2px 10px rgba(99,102,241,0.3); }
.auth-title { font-family: 'Outfit', sans-serif; font-size: 1.6rem; font-weight: 800; margin-bottom: 0.3rem; }
.auth-subtitle { color: var(--text-muted); font-size: 0.9rem; margin-bottom: 1.8rem; }

/* ---- Alerts / Toast ---- */
.toast {
  position: fixed; bottom: 2rem; right: 2rem; z-index: 9999;
  padding: 1rem 1.5rem; border-radius: var(--radius-md);
  font-weight: 600; font-size: 0.95rem;
  animation: toastIn 0.3s ease;
  max-width: 350px;
}
@keyframes toastIn { from { opacity: 0; transform: translateY(20px) scale(0.95); } to { opacity: 1; transform: translateY(0) scale(1); } }
.toast-success { background: rgba(16,185,129,0.15); border: 1px solid rgba(16,185,129,0.4); color: #6ee7b7; }
.toast-error { background: rgba(244,63,94,0.15); border: 1px solid rgba(244,63,94,0.4); color: #fda4af; }
.toast-info { background: rgba(99,102,241,0.15); border: 1px solid rgba(99,102,241,0.4); color: #a5b4fc; }

/* ---- Quiz Player ---- */
.quiz-page { min-height: 100vh; padding: 7rem 1rem 3rem; max-width: 800px; margin: 0 auto; position: relative; z-index: 1; }
.quiz-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 2rem; flex-wrap: wrap; gap: 1rem; }
.quiz-progress-wrap { flex: 1; }
.quiz-progress-info { display: flex; justify-content: space-between; font-size: 0.85rem; color: var(--text-muted); margin-bottom: 0.5rem; }
.progress-bar-outer { height: 6px; background: rgba(99,102,241,0.15); border-radius: 3px; overflow: hidden; }
.progress-bar-inner { height: 100%; background: var(--gradient-main); border-radius: 3px; transition: width 0.5s ease; }

/* Timer */
.timer-wrap { position: relative; width: 64px; height: 64px; flex-shrink: 0; }
.timer-svg { width: 64px; height: 64px; transform: rotate(-90deg); }
.timer-bg { fill: none; stroke: rgba(99,102,241,0.15); stroke-width: 4; }
.timer-ring { fill: none; stroke-width: 4; stroke-linecap: round; transition: stroke 0.5s ease; }
.timer-text {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-family: 'Outfit', sans-serif; font-weight: 700; font-size: 1rem;
}

/* Question Card */
.question-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-xl); padding: 2rem;
  box-shadow: var(--shadow-card); margin-bottom: 1.5rem;
  animation: fadeSlideIn 0.4s ease;
}
.question-type-badge {
  display: inline-block; padding: 0.25rem 0.7rem; border-radius: var(--radius-full);
  font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px;
  background: rgba(99,102,241,0.12); color: var(--accent-blue);
  margin-bottom: 1rem;
}
.question-text { font-family: 'Outfit', sans-serif; font-size: 1.2rem; font-weight: 700; margin-bottom: 1.5rem; line-height: 1.5; }

.options-grid { display: flex; flex-direction: column; gap: 0.75rem; }
.option-btn {
  padding: 1rem 1.25rem; border-radius: var(--radius-md);
  border: 1px solid var(--border-color); background: rgba(255,255,255,0.03);
  color: var(--text-primary); font-size: 0.95rem; font-weight: 500;
  cursor: pointer; transition: var(--transition); text-align: left;
  display: flex; align-items: center; gap: 0.8rem;
}
.option-btn:hover:not(:disabled) { border-color: var(--border-hover); background: rgba(99,102,241,0.08); transform: translateX(4px); }
.option-btn.correct { background: rgba(16,185,129,0.12); border-color: rgba(16,185,129,0.5); color: #6ee7b7; animation: pulseGreen 0.5s ease; }
.option-btn.incorrect { background: rgba(244,63,94,0.12); border-color: rgba(244,63,94,0.5); color: #fda4af; animation: shakeX 0.4s ease; }
.option-btn:disabled { cursor: not-allowed; }
.option-letter {
  width: 28px; height: 28px; border-radius: 50%;
  background: rgba(99,102,241,0.15); display: flex; align-items: center; justify-content: center;
  font-size: 0.8rem; font-weight: 700; flex-shrink: 0;
}

.fill-input-wrap { display: flex; gap: 0.75rem; }
.fill-input-wrap .form-input { flex: 1; }

.explanation-box {
  margin-top: 1rem; padding: 1rem;
  background: rgba(16,185,129,0.08); border: 1px solid rgba(16,185,129,0.25);
  border-radius: var(--radius-md); font-size: 0.9rem; color: var(--text-secondary);
}
.explanation-box strong { color: var(--accent-emerald); }

/* ---- Result Screen ---- */
.result-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-xl); padding: 2.5rem; text-align: center;
  box-shadow: var(--shadow-glow); animation: fadeSlideIn 0.5s ease;
}
.result-score-ring {
  width: 140px; height: 140px; margin: 0 auto 1.5rem;
  position: relative; display: flex; align-items: center; justify-content: center;
}
.result-score-svg { width: 140px; height: 140px; transform: rotate(-90deg); position: absolute; }
.score-bg { fill: none; stroke: rgba(99,102,241,0.15); stroke-width: 8; }
.score-fill { fill: none; stroke-width: 8; stroke-linecap: round; transition: stroke-dashoffset 1.5s cubic-bezier(0.4,0,0.2,1); }
.score-text-inner { font-family: 'Outfit', sans-serif; font-size: 2rem; font-weight: 900; }
.result-grade {
  font-size: 1.5rem; font-weight: 800; font-family: 'Outfit', sans-serif;
  margin-bottom: 0.5rem;
}
.result-title { font-family: 'Outfit', sans-serif; font-size: 1.8rem; font-weight: 900; margin-bottom: 0.5rem; }
.result-subtitle { color: var(--text-secondary); margin-bottom: 2rem; }
.result-stats { display: flex; justify-content: center; gap: 2rem; margin-bottom: 2rem; flex-wrap: wrap; }
.result-stat { text-align: center; }
.result-stat-num { font-family: 'Outfit', sans-serif; font-size: 1.5rem; font-weight: 800; }
.result-stat-label { font-size: 0.8rem; color: var(--text-muted); }
.result-actions { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }

/* ---- Leaderboard ---- */
.lb-page { min-height: 100vh; padding: 7rem 1rem 3rem; max-width: 900px; margin: 0 auto; position: relative; z-index: 1; }
.lb-table { width: 100%; border-collapse: collapse; }
.lb-table thead th {
  padding: 1rem 1.2rem; text-align: left;
  font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.5px;
  color: var(--text-muted); font-weight: 600;
  border-bottom: 1px solid var(--border-color);
}
.lb-row { transition: var(--transition); }
.lb-row td { padding: 1rem 1.2rem; border-bottom: 1px solid rgba(99,102,241,0.06); font-size: 0.95rem; }
.lb-row:hover td { background: rgba(99,102,241,0.04); }
.lb-rank { font-family: 'Outfit', sans-serif; font-weight: 800; font-size: 1.1rem; }
.rank-gold { color: #fbbf24; }
.rank-silver { color: #94a3b8; }
.rank-bronze { color: #b45309; }
.lb-user { display: flex; align-items: center; gap: 0.75rem; }
.lb-avatar {
  width: 36px; height: 36px; border-radius: 50%;
  background: var(--gradient-main);
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 0.85rem; flex-shrink: 0;
}
.lb-score { font-weight: 700; color: var(--accent-blue); }

/* ---- Admin Layout ---- */
.admin-layout { display: flex; min-height: 100vh; }
.admin-sidebar {
  width: 240px; flex-shrink: 0;
  background: var(--bg-secondary); border-right: 1px solid var(--border-color);
  padding: 5rem 1rem 1rem; position: fixed; top: 0; left: 0; height: 100%;
  overflow-y: auto; z-index: 100;
}
.sidebar-nav { display: flex; flex-direction: column; gap: 0.25rem; }
.sidebar-link {
  display: flex; align-items: center; gap: 0.7rem;
  padding: 0.75rem 1rem; border-radius: var(--radius-md);
  color: var(--text-secondary); font-size: 0.9rem; font-weight: 500;
  transition: var(--transition); cursor: pointer;
}
.sidebar-link:hover, .sidebar-link.active { background: rgba(99,102,241,0.12); color: var(--text-primary); }
.sidebar-link.active { background: rgba(99,102,241,0.15); color: var(--accent-blue); }
.sidebar-label { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; color: var(--text-muted); padding: 1rem 1rem 0.25rem; font-weight: 600; }

.admin-main { margin-left: 240px; flex: 1; padding: 5.5rem 2rem 2rem; }
.admin-page-header { margin-bottom: 2rem; }
.admin-page-title { font-family: 'Outfit', sans-serif; font-size: 1.8rem; font-weight: 800; }
.admin-page-sub { color: var(--text-muted); margin-top: 0.25rem; }

.stats-row { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 1rem; margin-bottom: 2rem; }
.stat-box {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 1.3rem 1.5rem;
}
.stat-box-num { font-family: 'Outfit', sans-serif; font-size: 2rem; font-weight: 900; }
.stat-box-label { font-size: 0.8rem; color: var(--text-muted); margin-top: 0.2rem; }
.stat-box-blue .stat-box-num { color: var(--accent-blue); }
.stat-box-green .stat-box-num { color: var(--accent-emerald); }
.stat-box-purple .stat-box-num { color: var(--accent-purple); }
.stat-box-amber .stat-box-num { color: var(--accent-amber); }

/* ---- Tables (Admin) ---- */
.table-card {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); overflow: hidden;
}
.table-header { padding: 1.2rem 1.5rem; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--border-color); }
.table-title { font-family: 'Outfit', sans-serif; font-weight: 700; font-size: 1rem; }
.data-table { width: 100%; border-collapse: collapse; }
.data-table thead th { padding: 0.9rem 1.2rem; text-align: left; font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.5px; color: var(--text-muted); background: rgba(99,102,241,0.04); border-bottom: 1px solid var(--border-color); }
.data-table tbody td { padding: 1rem 1.2rem; border-bottom: 1px solid rgba(99,102,241,0.05); font-size: 0.9rem; }
.data-table tbody tr:last-child td { border-bottom: none; }
.data-table tbody tr:hover td { background: rgba(99,102,241,0.03); }
.action-btns { display: flex; gap: 0.5rem; }

/* ---- Question Editor (Admin) ---- */
.question-editor {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-lg); padding: 1.5rem; margin-bottom: 1rem;
  position: relative;
}
.q-editor-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 1.2rem; }
.q-editor-num { font-weight: 700; color: var(--accent-blue); font-size: 0.9rem; }
.option-row { display: flex; gap: 0.5rem; margin-bottom: 0.5rem; align-items: center; }
.correct-radio { width: 18px; height: 18px; accent-color: var(--accent-emerald); cursor: pointer; flex-shrink: 0; }

/* ---- Page Helpers ---- */
.page-wrap { min-height: 100vh; padding: 7rem 1rem 3rem; max-width: 1100px; margin: 0 auto; position: relative; z-index: 1; }
.page-header { margin-bottom: 2rem; }
.page-title { font-family: 'Outfit', sans-serif; font-size: 2rem; font-weight: 800; margin-bottom: 0.3rem; }
.page-sub { color: var(--text-muted); }

.filter-bar { display: flex; gap: 0.75rem; flex-wrap: wrap; margin-bottom: 2rem; }
.filter-btn {
  padding: 0.4rem 1rem; border-radius: var(--radius-full);
  border: 1px solid var(--border-color); background: rgba(99,102,241,0.06);
  color: var(--text-secondary); font-size: 0.85rem; font-weight: 500;
  cursor: pointer; transition: var(--transition);
}
.filter-btn:hover, .filter-btn.active { border-color: var(--accent-blue); color: var(--accent-blue); background: rgba(99,102,241,0.12); }

.search-wrap { position: relative; margin-bottom: 1.5rem; max-width: 400px; }
.search-icon { position: absolute; left: 1rem; top: 50%; transform: translateY(-50%); color: var(--text-muted); pointer-events: none; }
.search-input { padding-left: 2.8rem !important; }

/* ---- Empty State ---- */
.empty-state {
  text-align: center; padding: 3rem; color: var(--text-muted);
  grid-column: 1/-1; font-size: 0.95rem;
}
.empty-state a { color: var(--accent-blue); text-decoration: underline; }

/* ---- Modal ---- */
.modal-overlay {
  position: fixed; inset: 0; z-index: 2000;
  background: rgba(0,0,0,0.7); backdrop-filter: blur(4px);
  display: flex; align-items: center; justify-content: center; padding: 1rem;
  animation: fadeIn 0.2s ease;
}
.modal {
  background: var(--bg-card); border: 1px solid var(--border-color);
  border-radius: var(--radius-xl); padding: 2rem; width: 100%; max-width: 500px;
  box-shadow: var(--shadow-glow-strong); animation: fadeSlideIn 0.3s ease;
}
.modal-title { font-family: 'Outfit', sans-serif; font-size: 1.4rem; font-weight: 800; margin-bottom: 1.5rem; }
.modal-actions { display: flex; gap: 0.75rem; justify-content: flex-end; margin-top: 1.5rem; }

/* ---- Badges ---- */
.badge {
  display: inline-flex; align-items: center; padding: 0.25rem 0.65rem;
  border-radius: var(--radius-full); font-size: 0.75rem; font-weight: 600;
}
.badge-blue { background: rgba(99,102,241,0.15); color: var(--accent-blue); }
.badge-green { background: rgba(16,185,129,0.15); color: var(--accent-emerald); }
.badge-amber { background: rgba(245,158,11,0.15); color: var(--accent-amber); }
.badge-rose { background: rgba(244,63,94,0.15); color: var(--accent-rose); }
.badge-purple { background: rgba(139,92,246,0.15); color: var(--accent-purple); }

/* ---- Footer ---- */
.footer { border-top: 1px solid var(--border-color); padding: 3rem 0 1.5rem; position: relative; z-index: 1; }
.footer-content { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1.5rem; margin-bottom: 2rem; }
.footer-brand { display: flex; flex-direction: column; gap: 0.4rem; }
.footer-brand p { color: var(--text-muted); font-size: 0.88rem; margin-top: 0.3rem; }
.footer-links { display: flex; gap: 1.5rem; flex-wrap: wrap; }
.footer-links a { color: var(--text-muted); font-size: 0.88rem; transition: var(--transition); }
.footer-links a:hover { color: var(--accent-blue); }
.footer-bottom { text-align: center; padding-top: 1.5rem; border-top: 1px solid var(--border-color); }
.footer-bottom p { color: var(--text-muted); font-size: 0.82rem; }

/* ---- Animations ---- */
@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes pulseGreen {
  0% { box-shadow: 0 0 0 0 rgba(16,185,129,0.5); }
  70% { box-shadow: 0 0 0 8px rgba(16,185,129,0); }
  100% { box-shadow: 0 0 0 0 rgba(16,185,129,0); }
}
@keyframes shakeX {
  0%, 100% { transform: translateX(0); }
  20%, 60% { transform: translateX(-6px); }
  40%, 80% { transform: translateX(6px); }
}
.animate-in { animation: fadeSlideIn 0.5s ease both; }

/* ---- Utility ---- */
.hidden { display: none !important; }
.flex { display: flex; }
.items-center { align-items: center; }
.gap-1 { gap: 0.5rem; }
.mt-1 { margin-top: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.text-muted { color: var(--text-muted); }
.text-accent { color: var(--accent-blue); }
.w-full { width: 100%; }
.divider { height: 1px; background: var(--border-color); margin: 1.5rem 0; }

/* ---- Responsive ---- */
@media (max-width: 900px) {
  .hero { flex-direction: column; text-align: center; padding-top: 6rem; gap: 2rem; }
  .hero-desc { margin: 0 auto 2rem; }
  .hero-actions { justify-content: center; }
  .hero-stats { justify-content: center; }
  .hero-visual { width: 100%; max-width: 360px; margin: 0 auto; }
  .admin-sidebar { transform: translateX(-100%); transition: transform 0.3s ease; }
  .admin-sidebar.open { transform: translateX(0); }
  .admin-main { margin-left: 0; }
}
@media (max-width: 600px) {
  .nav-links { display: none; flex-direction: column; position: absolute; top: 100%; left: 0; right: 0; background: var(--bg-secondary); border-bottom: 1px solid var(--border-color); padding: 1rem; gap: 0.3rem; }
  .nav-links.open { display: flex; }
  .hamburger { display: block; }
  .quiz-grid { grid-template-columns: 1fr; }
  .hero-title { font-size: 2rem; }
  .result-stats { gap: 1rem; }
  .filter-bar { gap: 0.5rem; }
}

